function ExistenceTest(points p[1..m] in Q^d, weights w[1..m] in Q):
    W <- sum_{i=1..m} w[i]
    if W = 0: abort  // degenerate datum
    for j in 1..d:
        M[j] <- sum_{i=1..m} w[i] * p[i][j]
    if M = 0:
        return (BALANCED, KE metric exists, no destabilizer)
    else:
        return (OBSTRUCTED, no KE metric, destabilizing xi = M)

function CertifiedBySymmetry(points, weights, sigma, perm):
    // 1. verify symmetry
    for i in 1..m:
        if weights[perm[i]] != weights[i]: return False
        if sigma * points[i] != points[perm[i]]: return False
    // 2. compute fixed space of sigma
    A <- sigma - I
    r <- rank(A) by exact Gaussian elimination over Q
    // 3. trivial fixed space => moment vector forced to 0
    return (r = d)
